INSERT INTO `settings` (`id`, `app_name`, `title`, `primary_phone`, `secondary_phone`, `primary_email`, `secondary_email`, `office_time`, `address`, `tax`, `discount`, `discount_type`, `description`, `banner_one`, `banner_one_link`, `banner_one_status`, `banner_two`, `banner_two_link`, `banner_two_status`, `page_heading_bg`, `meta_title`, `meta_keyword`, `meta_description`, `meta_image`, `google_map`, `favicon`, `logo`, `footer_logo`, `placeholder`, `facebook_page`, `facebook_group`, `youtube`, `twitter`, `linkedin`, `google`, `whatsapp`, `instagram`, `pinterest`, `sms_api_url`, `sms_api_key`, `sms_api_id`, `bkash_status`, `nagad_status`, `created_at`, `updated_at`) VALUES
(1, 'বুকস অ্যান্ড বুকস |  Online Book Publications', 'বুকস অ্যান্ড বুকস |  Online Book Publications', '01805030066', '01805030066', 'info@booksandbooksbd.com', 'books@gmail.com', NULL, '৩১৬/২ ডিআইটি রোড, পূর্ব রামপুরা, ঢাকা – ১২১৯', 15, 10, 'percent', 'বুকস অ্যান্ড বুকস একটি অনলাইন বইভিত্তিক প্ল্যাটফর্ম যেখানে পাঠকদের জন্য বিভিন্ন ধরনের মানসম্মত বই সহজে পাওয়ার সুযোগ তৈরি করা হয়েছে। আমাদের লক্ষ্য হলো বইকে মানুষের কাছে আরও সহজলভ্য করা এবং পাঠাভ্যাসকে উৎসাহিত করা। এখানে আপনি সাহিত্য, ইসলামিক, শিক্ষামূলক, গল্প, উপন্যাসসহ বিভিন্ন ধরনের বই  এক জায়গা থেকেই সংগ্রহ করতে পারবেন। আমরা চেষ্টা করি পাঠকদের কাছে বিশ্বস্ত সেবা এবং সেরা বইগুলো পৌঁছে দিতে। বুকস অ্যান্ড বুকস শুধু বই বিক্রির একটি প্ল্যাটফর্ম নয়, এটি বইপ্রেমীদের জন্য একটি কমিউনিটি যেখানে জ্ঞান, শিক্ষা এবং সৃজনশীলতার বিকাশকে গুরুত্ব দেওয়া হয়।', 'storage/settings/2026-02-02-GF8iNzEQw10DQX3hGgXKvIxe4fI7GR7kjt8TCcXZ.webp', NULL, 1, NULL, NULL, 1, 'storage/settings/2026-02-02-6btudjpIhD9wkXsltv1kfnMekRN4YTuKpP1eUaQT.webp', 'বুকস অ্যান্ড বুকস |  Online Book Publications', 'বই, অনলাইন বই, বই বিক্রি, কমিশন, ঘরে বসে আয়', 'বুকস অ্যান্ড বুকস একটি অনলাইন বইভিত্তিক প্ল্যাটফর্ম যেখানে পাঠকদের জন্য বিভিন্ন ধরনের মানসম্মত বই সহজে পাওয়ার সুযোগ তৈরি করা হয়েছে। আমাদের লক্ষ্য হলো বইকে মানুষের কাছে আরও সহজলভ্য করা এবং পাঠাভ্যাসকে উৎসাহিত করা।', 'storage/settings/2026-04-21-irNBDQZQL7XZZ7YC8DMKXlSOQiL73ZnHdMj32bsX.webp', NULL, 'storage/settings/2026-01-21-V4Q3LAERhKBYrp5zL6fOf2BdZ83NJFuqn0lf317n.webp', 'storage/settings/2026-05-12-fcOAVw6Vq3lA3GzxjqtRLOAlw9peufU3Nfv0cFt1.webp', NULL, 'storage/settings/2026-02-02-JYguxUfcqzekqfG4Eh7ZmqP2bzGXy1Iuv5UxSuLC.webp', 'https://www.facebook.com/', NULL, 'https://www.youtube.com/', 'https://www.twitter.com/', NULL, NULL, 'https://www.whatsapp.com/', 'https://www.Instagram.com/', 'https://www.pinterest.com/', NULL, NULL, NULL, 1, 1, '2026-01-19 05:10:51', '2026-05-21 02:04:57');
